import java.io.*;

public class Main {
    static byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;
    static InputStream in = System.in;

    static int read() throws IOException {
        if (ptr == len) { len = in.read(buf, 0, buf.length); ptr = 0; if (len <= 0) return -1; }
        return buf[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != '-' && (c < '0' || c > '9')) c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + c - '0'; c = read(); }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException { return (int) nextLong(); }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] r = new long[n], s = new long[n];
        for (int i = 0; i < n; i++) r[i] = nextLong();
        for (int i = 0; i < n; i++) s[i] = nextLong();
        // P: prefix of strategy*rate (profit), Q: prefix of rates.
        long[] P = new long[n + 1], Q = new long[n + 1];
        for (int i = 0; i < n; i++) { P[i + 1] = P[i] + s[i] * r[i]; Q[i + 1] = Q[i] + r[i]; }
        long base = P[n], best = base; // not modifying is allowed
        int h = k / 2;
        for (int l = 0; l + k <= n; l++) {
            // Window [l, l+k): drop its old contribution, the second half all sells.
            long v = base - (P[l + k] - P[l]) + (Q[l + k] - Q[l + h]);
            best = Math.max(best, v);
        }
        System.out.println(best);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var rd = bufio.NewReaderSize(os.Stdin, 1<<20)

func readInt() int {
	n := 0
	c, _ := rd.ReadByte()
	for c == ' ' || c == '\n' || c == '\r' {
		c, _ = rd.ReadByte()
	}
	neg := c == '-'
	if neg {
		c, _ = rd.ReadByte()
	}
	for c >= '0' && c <= '9' {
		n = n*10 + int(c-'0')
		c, _ = rd.ReadByte()
	}
	if neg {
		return -n
	}
	return n
}

func main() {
	n, k := readInt(), readInt()
	r, s := make([]int, n), make([]int, n)
	for i := range r {
		r[i] = readInt()
	}
	for i := range s {
		s[i] = readInt()
	}
	// P: prefix of strategy*rate (profit), Q: prefix of rates.
	P, Q := make([]int, n+1), make([]int, n+1)
	for i := 0; i < n; i++ {
		P[i+1] = P[i] + s[i]*r[i]
		Q[i+1] = Q[i] + r[i]
	}
	base := P[n]
	best := base // not modifying is allowed
	h := k / 2
	for l := 0; l+k <= n; l++ {
		// Window [l, l+k): drop its old contribution, the second half all sells.
		best = max(best, base-(P[l+k]-P[l])+(Q[l+k]-Q[l+h]))
	}
	fmt.Println(best)
}
